package org.example.strategy_pattern.spring_boot.impl;import org.example.strategy_pattern.delivery.EShippingType;import org.example.strategy_pattern.delivery.Order;import org.example.strategy_pattern.spring_boot.ShippingStrategy;import org.springframework.stereotype.Component;@Componentpublic class ExpressShippingStrategy implements ShippingStrategy {    public EShippingType getType() {        return EShippingType.EXPRESS;    }    public int calculateFee(Order order) {        int df = 50;        return order.getWeightInGram() > 1000 ? df + 10 : df;    }}